  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Es wird spät','دارد دیر می‌شود','Lena und Ben wählen trotz der späten Uhrzeit die bessere Verbindung.','لنا و بن با وجود دیر بودن ساعت، مسیر بهتر را انتخاب می‌کنند.','story','lena-ben-b1-travel-problems',9,51,175,1,'validated','{"relationship":"friends","context":"late-travel","cefr":"B1","storyArc":"continue-despite-obstacles"}');
