  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,1,'character','Es ist schon spät, aber unser Zug fährt gleich ab.','دیر شده، اما قطارمان به‌زودی حرکت می‌کند.',51,NULL,NULL,NULL,NULL,'[{"lemma":"es","partOfSpeech":"pronoun","surface":"Es","translation":"آن / این / ضمیر خنثی"},{"lemma":"sein","partOfSpeech":"verb","surface":"ist","translation":"بودن"},{"lemma":"schon","partOfSpeech":"adverb","surface":"schon","translation":"قبلا / تا حالا"},{"lemma":"spät","partOfSpeech":"adjective","suffix":",","surface":"spät","translation":"دیر"},{"lemma":"aber","partOfSpeech":"conjunction","surface":"aber","translation":"اما"},{"lemma":"unser","partOfSpeech":"determiner","surface":"unser","translation":"مال ما / ما"},{"lemma":"Zug","partOfSpeech":"noun","surface":"Zug","translation":"قطار"},{"lemma":"fahren","partOfSpeech":"verb","surface":"fährt","translation":"رفتن با وسیله / راندن"},{"lemma":"gleich","partOfSpeech":"adverb","surface":"gleich","translation":"همین الان"},{"lemma":"ab","partOfSpeech":"particle","suffix":".","surface":"ab","translation":"جدا / ارسال"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_1=LAST_INSERT_ID();
