  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,3,'character','Die Fahrt nach Frankfurt dauert ungefähr zwei Stunden.','سفر تا فرانکفورت حدود دو ساعت طول می‌کشد.',51,NULL,NULL,NULL,NULL,'[{"lemma":"der","partOfSpeech":"article","surface":"Die","translation":"حرف تعریف"},{"lemma":"Fahrt","partOfSpeech":"noun","surface":"Fahrt","translation":"سفر / مسیر"},{"lemma":"nach","partOfSpeech":"preposition","surface":"nach","translation":"پس از / به"},{"lemma":"Frankfurt","partOfSpeech":"noun","surface":"Frankfurt","translation":"فرانکفورت"},{"lemma":"dauern","partOfSpeech":"verb","surface":"dauert","translation":"طول کشیدن"},{"lemma":"ungefähr","partOfSpeech":"adverb","surface":"ungefähr","translation":"حدود / تقریباً"},{"lemma":"zwei","partOfSpeech":"number","surface":"zwei","translation":"دو"},{"lemma":"Stunde","partOfSpeech":"noun","suffix":".","surface":"Stunden","translation":"ساعت / یک ساعت"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
