  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Ein weiterer Umstieg','یک تعویض قطار دیگر','In Frankfurt bleibt nur wenig Zeit für den nächsten Anschluss.','در فرانکفورت زمان کمی برای رسیدن به قطار بعدی باقی می‌ماند.','story','lena-ben-b1-travel-problems',11,51,175,3,'validated','{"relationship":"friends","context":"late-travel","cefr":"B1","storyArc":"continue-despite-obstacles"}');
  SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_ben,1,'character','In Frankfurt müssen wir auf Gleis zwölf umsteigen.','در فرانکفورت باید در سکوی دوازده قطار عوض کنیم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"in","partOfSpeech":"preposition","surface":"In","translation":"در / داخل"},{"lemma":"Frankfurt","partOfSpeech":"noun","surface":"Frankfurt","translation":"فرانکفورت"},{"lemma":"müssen","partOfSpeech":"verb","surface":"müssen","translation":"مجبور بودن / باید"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"auf","partOfSpeech":"preposition","surface":"auf","translation":"روی / برای"},{"lemma":"Gleis","partOfSpeech":"noun","surface":"Gleis","translation":"سکوی قطار / خط"},{"lemma":"zwölf","partOfSpeech":"number","surface":"zwölf","translation":"دوازده"},{"lemma":"umsteigen","partOfSpeech":"verb","suffix":".","surface":"umsteigen","translation":"قطار عوض کردن / خط عوض کردن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_13=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_lena,2,'learner','Obwohl die Umsteigezeit kurz ist, schaffen wir das.','با اینکه زمان تعویض قطار کوتاه است، از پسش برمی‌آییم.',51,NULL,NULL,'obwohl die umsteigezeit kurz ist schaffen wir das',NULL,'[{"lemma":"obwohl","partOfSpeech":"conjunction","surface":"Obwohl","translation":"با اینکه"},{"lemma":"der","partOfSpeech":"article","surface":"die","translation":"حرف تعریف"},{"lemma":"Umsteigezeit","partOfSpeech":"noun","surface":"Umsteigezeit","translation":"زمان تعویض قطار"},{"lemma":"kurz","partOfSpeech":"adjective","surface":"kurz","translation":"کوتاه"},{"lemma":"sein","partOfSpeech":"verb","suffix":",","surface":"ist","translation":"بودن"},{"lemma":"schaffen","partOfSpeech":"verb","surface":"schaffen","translation":"از عهده برآمدن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"das","partOfSpeech":"pronoun","suffix":".","surface":"das","translation":"این / آن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_14=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_ben,3,'character','Der Anschluss wartet heute nicht auf verspätete Züge.','قطار بعدی امروز منتظر قطارهای دیرکرده نمی‌ماند.',51,NULL,NULL,NULL,NULL,'[{"lemma":"der","partOfSpeech":"article","surface":"Der","translation":"حرف تعریف"},{"lemma":"Anschluss","partOfSpeech":"noun","surface":"Anschluss","translation":"قطار بعدی / اتصال"},{"lemma":"warten","partOfSpeech":"verb","surface":"wartet","translation":"منتظر ماندن / صبر کردن"},{"lemma":"heute","partOfSpeech":"adverb","surface":"heute","translation":"امروز"},{"lemma":"nicht","partOfSpeech":"particle","surface":"nicht","translation":"نه / نیست"},{"lemma":"auf","partOfSpeech":"preposition","surface":"auf","translation":"روی / برای"},{"lemma":"verspätet","partOfSpeech":"adjective","surface":"verspätete","translation":"دیرکرده"},{"lemma":"Zug","partOfSpeech":"noun","suffix":".","surface":"Züge","translation":"قطار"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_15=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_lena,4,'learner','Dann gehen wir direkt zum anderen Gleis.','پس مستقیم به سکوی دیگر می‌رویم.',51,NULL,NULL,'dann gehen wir direkt zum anderen gleis',NULL,'[{"lemma":"dann","partOfSpeech":"adverb","surface":"Dann","translation":"بعد / سپس"},{"lemma":"gehen","partOfSpeech":"verb","surface":"gehen","translation":"رفتن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"direkt","partOfSpeech":"adverb","surface":"direkt","translation":"مستقیم"},{"lemma":"zu","partOfSpeech":"preposition","surface":"zum","translation":"به / به سمت"},{"lemma":"ander","partOfSpeech":"adjective","surface":"anderen","translation":"دیگر"},{"lemma":"Gleis","partOfSpeech":"noun","suffix":".","surface":"Gleis","translation":"سکوی قطار / خط"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
