  INSERT INTO activities(lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES(v_l_3,'meaning_choice',7,NULL,v_w_069,'معنی واژهٔ کلیدی را انتخاب کن',NULL,51,'{"mode":"word_translation","question":"Umsteigezeit در این درس چه معنی دارد؟","choices":["زمان تعویض قطار","خرید غذا","تعمیر خانه"],"correctIndex":0}','{"cefr":"B1","series":98}');
  INSERT INTO activities(lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES(v_l_3,'reading_comprehension',8,NULL,NULL,'مکالمه را بخوان و پاسخ بده',NULL,51,'{"source":"lesson_story","question":"آن‌ها در فرانکفورت چه کاری باید انجام دهند؟","choices":["سریع به سکوی دیگر بروند","از ایستگاه خارج شوند","یک شب بمانند"],"correctIndex":0}','{"cefr":"B1","series":98}');
  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Die Reise geht weiter','سفر ادامه دارد','Lena und Ben erreichen den Anschluss und informieren das Hotel über die neue Zeit.','لنا و بن به قطار بعدی می‌رسند و زمان جدید را به هتل اطلاع می‌دهند.','story','lena-ben-b1-travel-problems',12,51,175,4,'validated','{"relationship":"friends","context":"late-travel","cefr":"B1","storyArc":"continue-despite-obstacles"}');
