  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_ben,1,'character','Wir haben den Anschluss tatsächlich erreicht.','واقعاً به قطار بعدی رسیدیم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"wir","partOfSpeech":"pronoun","surface":"Wir","translation":"ما"},{"lemma":"haben","partOfSpeech":"verb","surface":"haben","translation":"داشتن"},{"lemma":"der","partOfSpeech":"article","surface":"den","translation":"حرف تعریف"},{"lemma":"Anschluss","partOfSpeech":"noun","surface":"Anschluss","translation":"قطار بعدی / اتصال"},{"lemma":"tatsächlich","partOfSpeech":"adverb","surface":"tatsächlich","translation":"واقعاً"},{"lemma":"erreichen","partOfSpeech":"verb","suffix":".","surface":"erreicht","translation":"رسیدن به"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_lena,2,'learner','Obwohl es spät ist, fahren wir weiter.','با اینکه دیر است، به مسیر ادامه می‌دهیم.',51,NULL,NULL,'obwohl es spät ist fahren wir weiter',NULL,'[{"lemma":"obwohl","partOfSpeech":"conjunction","surface":"Obwohl","translation":"با اینکه"},{"lemma":"es","partOfSpeech":"pronoun","surface":"es","translation":"آن / این / ضمیر خنثی"},{"lemma":"spät","partOfSpeech":"adjective","surface":"spät","translation":"دیر"},{"lemma":"sein","partOfSpeech":"verb","suffix":",","surface":"ist","translation":"بودن"},{"lemma":"fahren","partOfSpeech":"verb","surface":"fahren","translation":"رفتن با وسیله / راندن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"weiter","partOfSpeech":"adverb","suffix":".","surface":"weiter","translation":"ادامه / بیشتر"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_20=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_ben,3,'character','Jetzt können wir uns endlich etwas ausruhen.','حالا بالاخره می‌توانیم کمی استراحت کنیم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"jetzt","partOfSpeech":"adverb","surface":"Jetzt","translation":"حالا / اکنون"},{"lemma":"können","partOfSpeech":"verb","surface":"können","translation":"توانستن / بتوان"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"sich","partOfSpeech":"pronoun","surface":"uns","translation":"خود / خودش"},{"lemma":"endlich","partOfSpeech":"adverb","surface":"endlich","translation":"بالاخره"},{"lemma":"etwas","partOfSpeech":"pronoun","surface":"etwas","translation":"چیزی / یک چیزی"},{"lemma":"ausruhen","partOfSpeech":"verb","suffix":".","surface":"ausruhen","translation":"استراحت کردن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_21=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_lena,4,'learner','Ich melde dem Hotel unsere neue Ankunftszeit.','زمان رسیدن جدیدمان را به هتل اطلاع می‌دهم.',51,NULL,NULL,'ich melde dem hotel unsere neue ankunftszeit',NULL,'[{"lemma":"ich","partOfSpeech":"pronoun","surface":"Ich","translation":"من"},{"lemma":"melden","partOfSpeech":"verb","surface":"melde","translation":"اطلاع دادن"},{"lemma":"der","partOfSpeech":"article","surface":"dem","translation":"حرف تعریف"},{"lemma":"Hotel","partOfSpeech":"noun","surface":"Hotel","translation":"هتل"},{"lemma":"unser","partOfSpeech":"determiner","surface":"unsere","translation":"مال ما / ما"},{"lemma":"neu","partOfSpeech":"adjective","surface":"neue","translation":"جدید / تازه"},{"lemma":"Ankunftszeit","partOfSpeech":"noun","suffix":".","surface":"Ankunftszeit","translation":"زمان رسیدن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_22=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_ben,5,'character','In einer Stunde sind wir fast am Ziel.','یک ساعت دیگر تقریباً به مقصد می‌رسیم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"in","partOfSpeech":"preposition","surface":"In","translation":"در / داخل"},{"lemma":"ein","partOfSpeech":"article","surface":"einer","translation":"یک / حرف تعریف نامعین"},{"lemma":"Stunde","partOfSpeech":"noun","surface":"Stunde","translation":"ساعت / یک ساعت"},{"lemma":"sein","partOfSpeech":"verb","surface":"sind","translation":"بودن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"fast","partOfSpeech":"adverb","surface":"fast","translation":"تقریبا"},{"lemma":"an","partOfSpeech":"preposition","surface":"am","translation":"در / در روز"},{"lemma":"Ziel","partOfSpeech":"noun","suffix":".","surface":"Ziel","translation":"مقصد / هدف"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_23=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_lena,6,'learner','Gut, trotz der Probleme war unsere Entscheidung richtig.','خوب، با وجود مشکلات تصمیممان درست بود.',51,NULL,NULL,'gut trotz der probleme war unsere entscheidung richtig',NULL,'[{"lemma":"gut","partOfSpeech":"adjective","suffix":",","surface":"Gut","translation":"خوب"},{"lemma":"trotz","partOfSpeech":"preposition","surface":"trotz","translation":"با وجود"},{"lemma":"der","partOfSpeech":"article","surface":"der","translation":"حرف تعریف"},{"lemma":"Problem","partOfSpeech":"noun","surface":"Probleme","translation":"مشکل"},{"lemma":"sein","partOfSpeech":"verb","surface":"war","translation":"بودن"},{"lemma":"unser","partOfSpeech":"determiner","surface":"unsere","translation":"مال ما / ما"},{"lemma":"Entscheidung","partOfSpeech":"noun","surface":"Entscheidung","translation":"تصمیم"},{"lemma":"richtig","partOfSpeech":"adjective","suffix":".","surface":"richtig","translation":"درست"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
